class OtaUpdateState_Completed(pydantic.RootModel[Literal["completed"]]):
    pass


class OtaUpdateState_Failed(pydantic.RootModel[Literal["failed"]]):
    pass


class OtaUpdateState_Blocked(pydantic.RootModel[Literal["blocked"]]):
    pass


class OtaUpdateState_Rollback(pydantic.RootModel[Literal["rollback"]]):
    pass


# **Unstable (feature `ota_updates`).**
#
# OTA update state.
#
# The resting states are `idle`, `completed`, `failed`, and `blocked`.
# The integration remains in one of these until the next check begins or
# the blocking condition clears.
type OtaUpdateState = (
    OtaUpdateState_Idle
    | OtaUpdateState_Installing
    | OtaUpdateState_Rebooting
    | OtaUpdateState_Committing
    | OtaUpdateState_Completed
    | OtaUpdateState_Failed
    | OtaUpdateState_Blocked
    | OtaUpdateState_Rollback
)


